import {idlFactory} from './idl.js';
import {openShareDialog,showShared} from './sharing.js';
import {createEditor,toolbar} from './editor.js';
import {appSignIn,takeHubTicket,session,suiteCookie,mountTopbar,topbarIdlFactory} from './hub-client.js';
const BACKEND_CANISTER_ID = "__BACKEND_CANISTER_ID__";
const HUB_URL = "__HUB_URL__";
const APP_VERSION = "0.2.0";
try { if (localStorage.getItem('ks-theme')==='dark') document.documentElement.dataset.theme='dark'; } catch {}
session.key='ks-knowledge-session';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=n=>new Date(Number(n/1000000n)).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});
const opt=x=>x?.[0];
let api,me,editors=[],dirty=false,generation=0,topbar,routeHash='',busy=false;
const publicRoute=()=>location.hash.startsWith('#/s/');
const publicMode=publicRoute();
if(publicMode)$('login').hidden=true;
const signIn=publicMode?null:appSignIn({name:'Doku',hubUrl:HUB_URL});
const token=()=>session.load();
const reviewer=()=>['reviewer','admin'].includes(me?.role);
const author=()=>['author','reviewer','admin'].includes(me?.role);
function note(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
function result(r){if('err' in r)throw new Error(r.err);return r.ok;}
function documentAt(id,content,editable=false,onChange=()=>{}){const ed=createEditor($(id),{content:JSON.parse(content),editable,onChange});editors.push(ed);return ed;}
function clear(){document.querySelectorAll('dialog.share-dialog').forEach(d=>d.close());editors.forEach(e=>e.destroy());editors=[];dirty=false;note('');}
function button(id,fn){$(id).onclick=async()=>{if(busy)return;busy=true;$(id).disabled=true;try{await fn();}catch(e){note(e.message||'Connection interrupted. Retry to confirm the result.',true);}finally{busy=false;if($(id))$(id).disabled=false;}};}
function sourceBox(src){if(!src)return '<p class="muted">Written in Doku. Check the text and its intended audience before publishing.</p>';const url=src.url?new URL(src.url):null;if(url&&url.protocol==='https:')url.hash=`/t/${src.ticketId}`;return `<details class="source" open><summary>Confirmed Desk solution · ${esc(src.key)}</summary><p class="muted">${src.confirmed?'Confirmed':'Needs confirmation'} · ${src.confirmedAt?date(src.confirmedAt):'No confirmation yet'}</p><p class="source-text">${esc(src.summary)}</p>${url?.protocol==='https:'?`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">Open ticket ↗</a>`:''}</details>`;}
async function route(){
 if(!me)return;
 if(dirty&&location.hash!==routeHash&&!confirm('Leave this draft? Changes since your last save will be lost.')){history.replaceState(null,'',routeHash);return;}
 routeHash=location.hash;const stamp=++generation;clear();
 $('content').innerHTML='<p class="empty" role="status">Loading your workspace…</p>';
 document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));
 const [view,arg,ticket]=location.hash.replace(/^#\/?/,'').split('/');
 try{
 if(view==='new'){
  if(!author())throw new Error('Author access is required. Ask your Hub owner.');
  $('content').innerHTML='<div class="page-heading"><div><a class="back" href="#/library">← Library</a><p class="eyebrow">WRITE IN DOKU</p><h1>Share what you know.</h1><p class="muted">Create a draft, write your guide and have it reviewed before publication.</p></div></div><section class="panel new-article"><h2>Start with a blank page.</h2><p>Your draft is visible to you and Doku reviewers. You can save it and continue later.</p><button id="createManual" class="primary">Start writing</button></section>';
  const requestId=crypto.randomUUID();button('createManual',async()=>{const id=result(await api.createManualProposal(token(),[],requestId));if(stamp===generation)location.hash=`/proposal/${id}`;});
 }else if(view==='from-desk'){
  if(!author())throw new Error('Author access is required. Ask your Hub owner.');
  if(!/^\d+$/.test(arg)||!/^\d+$/.test(ticket))throw new Error('Invalid ticket link');
  const src=result(await api.source(token(),BigInt(arg),BigInt(ticket)));if(stamp!==generation)return;
  const options=[];let after=0n;do{const page=await api.articles(token(),'',after);options.push(...page.rows);after=opt(page.next);}while(after!==undefined&&options.length<1000);
  if(stamp!==generation)return;
  $('content').innerHTML=`<div class="page-heading"><div><p class="eyebrow">FROM DESK</p><h1>Turn a solution into knowledge.</h1><p class="muted">Start a new article or propose an update to an existing one.</p></div></div><div class="start-layout"><section class="panel">${sourceBox(src)}</section><section class="panel"><h2>Where does this belong?</h2><label for="target">Article</label><select id="target"><option value="">Create a new article</option>${options.map(a=>`<option value="${a.article}">${esc(a.title)}</option>`).join('')}</select><p class="muted">Your draft is visible to its author and Doku reviewers with Desk staff access. Publication is a separate step.</p><button id="create" class="primary" ${src.confirmed?'':'disabled'}>Create proposal</button>${src.confirmed?'':'<p>Confirm the solution in Desk first, then reload this page.</p>'}</section></div>`;
  const requestId=crypto.randomUUID();button('create',async()=>{const id=result(await api.createProposal(token(),{desk:BigInt(arg),ticket:BigInt(ticket),article:$('target').value?[BigInt($('target').value)]:[],requestId}));if(stamp!==generation)return;location.hash=`/proposal/${id}`;});
 }else if(view==='proposal'){
  const detail=result(await api.proposal(token(),BigInt(arg)));if(stamp!==generation)return;const p=detail.proposal,base=opt(detail.base),src=opt(detail.currentSource),originalSource=opt(p.source);
  const stale=(originalSource&&(!src?.confirmed||src.revision!==originalSource.revision||src.backend!==originalSource.backend))||(base?.revision??0n)!==p.baseRevision;
  let revision=p.revision;
  $('content').innerHTML=`<div class="page-heading"><div><a class="back" href="#/proposals">← Proposals</a><h1>${p.state==='draft'?'Review a documentation change.':'Proposal '+esc(p.state)}</h1><p class="muted">${p.article.length?'Update to version '+p.baseRevision:'New article'} · proposal ${p.id}</p></div><span class="badge">${esc(p.state)}</span></div>${stale?'<div class="warning">The source or published article changed. Keep this draft for reference and start a new proposal from the current version or solution.</div>':''}<div class="editor-layout"><section class="editor-panel"><label for="title">Article title</label><input id="title" class="title-input" maxlength="180" value="${esc(p.title)}" ${p.state==='draft'?'':'disabled'}><div id="toolbar" class="toolbar"></div><div id="editor"></div><div class="editor-foot"><span id="saved">Saved · ${date(p.updatedAt)}</span><button id="save" ${p.state==='draft'?'':'disabled'}>Save draft</button></div></section><aside class="review-side"><section class="panel"><h2>Source & review</h2>${sourceBox(originalSource)}${base?'<details><summary>Current published version</summary><div id="before"></div></details>':'<p class="muted">This will be the first published version.</p>'}</section><section class="panel"><h2>Publish intentionally.</h2><p>All people with Doku access can read the published article and its version history. Remove personal details and secrets from the text.</p><label class="check"><input id="audience" type="checkbox"> I reviewed the text and its audience.</label><button id="publish" class="primary" ${reviewer()&&p.state==='draft'&&!stale?'':'disabled'}>Approve & publish</button>${reviewer()?'':'<p class="muted">A reviewer or admin must approve this proposal.</p>'}<button id="discard" class="quiet" ${p.state==='draft'?'':'disabled'}>Discard proposal</button></section></aside></div>`;
  const editor=documentAt('editor',p.document,p.state==='draft',()=>{dirty=true;$('saved').textContent='Unsaved changes';});
  if(p.state==='draft')toolbar(editor,$('toolbar'));
  if(base)documentAt('before',base.document);
  $('title').oninput=()=>{dirty=true;$('saved').textContent='Unsaved changes';};
  button('save',async()=>{const title=$('title');editor.setEditable(false,false);title.disabled=true;$('toolbar').inert=true;try{const savedRevision=result(await api.saveProposal(token(),p.id,revision,{title:title.value,document:JSON.stringify(editor.getJSON())}));if(stamp!==generation)return;revision=savedRevision;dirty=false;$('saved').textContent='Saved just now';note('Draft saved. It is not published yet.');}finally{if(stamp===generation){editor.setEditable(true,false);title.disabled=false;$('toolbar').inert=false;}}});
  button('publish',async()=>{if(dirty)throw new Error('Save your draft before publishing.');if(!$('audience').checked)throw new Error('Confirm that you reviewed the text and its audience.');const id=result(await api.publishProposal(token(),p.id,revision));if(stamp!==generation)return;dirty=false;location.hash=`/article/${id}`;});
  button('discard',async()=>{if(!confirm('Discard this proposal? Published articles are kept.'))return;result(await api.discardProposal(token(),p.id,revision));if(stamp!==generation)return;dirty=false;location.hash='/proposals';});
 }else if(view==='article'){
  const a=opt(await api.article(token(),BigInt(arg)));if(!a)throw new Error('Article unavailable');
  const history=await api.history(token(),a.article);if(stamp!==generation)return;
  $('content').innerHTML=`<div class="page-heading"><div><a class="back" href="#/library">← Library</a><p class="eyebrow">PUBLISHED DOCUMENTATION</p><h1 id="articleTitle">${esc(a.title)}</h1><p class="muted" id="articleMeta">Version ${a.revision} · ${date(a.publishedAt)}</p></div><div class="heading-actions">${author()?'<button id="editArticle">Propose edit</button>':''}${reviewer()?'<button id="shareArticle" class="primary">Share</button>':''}</div></div><div class="reading-layout"><article class="paper"><div id="article"></div></article><aside class="panel"><h2>Version history</h2><label for="version">Read a version</label><select id="version">${[...history].reverse().map(v=>`<option value="${v.revision}">Version ${v.revision} · ${date(v.publishedAt)}</option>`).join('')}</select><p class="muted" id="historyNote">You are reading the current published version.</p><p class="muted">Propose an edit here, or start from a related resolved ticket in Desk. Each change is reviewed before publication.</p></aside></div>`;
  const requestId=crypto.randomUUID();if(author())button('editArticle',async()=>{const id=result(await api.createManualProposal(token(),[a.article],requestId));if(stamp===generation)location.hash=`/proposal/${id}`;});
  let displayedRevision=a.revision;
  if(reviewer())button('shareArticle',()=>openShareDialog({api,token,article:a.article,revision:displayedRevision}));
  let ed=documentAt('article',a.document);
  $('version').onchange=async()=>{const selected=$('version').value;if($('shareArticle'))$('shareArticle').disabled=true;try{const old=opt(await api.articleVersion(token(),a.article,BigInt(selected)));if(stamp!==generation||$('version').value!==selected)return;if(!old)throw new Error('Version unavailable');ed.commands.setContent(JSON.parse(old.document));displayedRevision=old.revision;$('articleTitle').textContent=old.title;$('articleMeta').textContent=`Version ${old.revision} · ${date(old.publishedAt)}`;$('historyNote').textContent=old.revision===a.revision?'You are reading the current published version.':'Historical version — the current article remains unchanged.';}catch{if(stamp===generation&&$('version').value===selected){$('version').value=String(displayedRevision);note('Version could not be loaded. The displayed version is unchanged.',true);}}finally{if(stamp===generation&&$('shareArticle'))$('shareArticle').disabled=$('version').value!==String(displayedRevision);}};
 }else if(view==='proposals'){
  if(!author())throw new Error('Author access is required.');
  $('content').innerHTML='<div class="page-heading"><div><p class="eyebrow">HUMAN REVIEW</p><h1>Proposals</h1><p class="muted">Open a draft to check the source, edit the text and review publication.</p></div></div><div id="rows" class="list"></div><button id="more">Load more</button>';
  let cursor=0n;async function more(){const rows=await api.proposals(token(),cursor);if(stamp!==generation)return;$('rows').insertAdjacentHTML('beforeend',rows.map(p=>`<a class="list-row" href="#/proposal/${p.id}"><span><strong>${p.manual?'Written in Doku':'Desk'} proposal ${p.id}</strong><small>${p.own?'Your draft':'Ready for review'} · ${date(p.updatedAt)}</small></span><span aria-hidden="true">→</span></a>`).join(''));if(rows.length)cursor=rows.at(-1).id;$('more').hidden=rows.length<30;if(!cursor)$('rows').innerHTML='<div class="empty"><h2>Nothing waiting for review.</h2><p>Create an article in the library, or start from a resolved Desk ticket.</p></div>';}
  button('more',more);await more();
 }else if(view==='help'){
  $('content').innerHTML=`<article class="paper guide"><p class="eyebrow">DOKU ${APP_VERSION} · ALPHA</p><h1>Useful knowledge, with a review step.</h1><ol><li>Choose Create article in the library to write directly, or resolve an internal Desk ticket.</li><li>For a Desk ticket, confirm a concise, reusable solution under Documentation.</li><li>Create a proposal for a new or existing article.</li><li>Edit and save using the formatting toolbar.</li><li>A reviewer checks the source, existing version and audience, then publishes.</li></ol><p>Readers see published articles. Authors manage their drafts. Reviewers and admins can edit and approve proposals, including their own; this release does not enforce two-person review. Desk-sourced drafts additionally require current Desk staff access. Manually written drafts do not need Desk access.</p><p>A reopened ticket, changed solution or concurrent article update blocks publication. Start a new proposal from the current source. Saving never replaces the published version. Old published versions remain readable.</p><p>Automatic AI proposals, Slack reminders, separate spaces, images and attachments are planned. Reviewers and admins can share a published version externally using Share. Choose 1, 7, 30 or a custom number of days, or Never; a password is optional. Links default to seven days and can be revoked from the same dialog. Each link exposes only the selected version, with no ticket, draft or history. Copies already made cannot be recalled. The link uses a compact random code on this app’s address; no external shortener is involved. The editor supports paragraphs, headings, lists, bold, italic, quotes and code blocks. Pasted links are plain text.</p><p>Drafts must be saved explicitly. Unsaved text stays only in this open page. Pilot limits: 50,000 text characters and 2,000 nodes per document, 1,000 articles, 10,000 proposals and 100 versions per article. No automatic deletion or archive policy is provided.</p><p>Access is managed in Hub → Permissions. Operator work includes role assignment, source review, updates and backups. No external AI receives content in this milestone.</p><a href="./CHANGELOG.md">Release notes</a> · <a href="./third-party-notices.txt">Editor licenses</a></article>`;
 }else{
  $('content').innerHTML='<div class="page-heading"><div><p class="eyebrow">TEAM KNOWLEDGE</p><h1>A place for what you learned.</h1><p class="muted">Reviewed guides and solutions, kept close to the work.</p></div>'+(author()?'<a class="button primary" href="#/new">Create article</a>':'')+'</div><label class="search-label" for="search">Search documentation</label><div class="search"><input id="search" type="search" placeholder="Find a guide or solution…" maxlength="200"><button id="find">Search</button></div><div id="rows" class="list"></div><button id="more">Load more</button>';
  let cursor=0n,q='';async function more(){let page;do{page=await api.articles(token(),q,cursor);if(stamp!==generation)return;cursor=opt(page.next);}while(q&&!page.rows.length&&cursor!==undefined);$('rows').insertAdjacentHTML('beforeend',page.rows.map(a=>`<a class="list-row" href="#/article/${a.article}"><span><strong>${esc(a.title)}</strong><small>Version ${a.revision} · ${date(a.publishedAt)}</small></span><span aria-hidden="true">→</span></a>`).join(''));cursor=opt(page.next);$('more').hidden=cursor===undefined;if(!$('rows').children.length)$('rows').innerHTML=`<div class="empty"><h2>${q?'No matching articles.':'Your first useful guide starts here.'}</h2><p>${q?'Try a different search term.':(author()?'Create an article, or turn a resolved Desk ticket into documentation.':'Published guides will appear here once a reviewer approves them.')}</p></div>`;}
  button('more',more);button('find',async()=>{cursor=0n;q=$('search').value.trim();$('rows').replaceChildren();await more();});$('search').onkeydown=e=>{if(e.key==='Enter')$('find').click();};await more();
 }
 }catch(e){if(stamp!==generation)return;$('content').innerHTML='<div class="empty"><h1>This view is unavailable.</h1><p id="viewError"></p><button id="retry">Try again</button></div>';$('viewError').textContent=e.message||'The connection was interrupted.';$('retry').onclick=route;}
}
async function signOut(){if(dirty&&!confirm('Sign out and discard unsaved changes?'))return;try{await api.signOut(token());}catch{}session.clear();suiteCookie.clear();location.reload();}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{if(publicMode||publicRoute())location.reload();else route();});
$('loginBtn').onclick=()=>signIn?.continue();
async function start(){try{
 const {HttpAgent,Actor}=await import('./agent-bundle.js');const agent=await HttpAgent.create({host:'https://icp0.io'});api=Actor.createActor(idlFactory,{agent,canisterId:BACKEND_CANISTER_ID});
 if(publicMode){await showShared({api,code:location.hash.slice(4),root:$('shared')});return;}
 const ticket=takeHubTicket();let login;if(ticket){session.clear();login=opt(await api.loginWithTicket(ticket));if(!login)throw new Error('Sign-in was not accepted. Please try again.');}else if(!token()&&suiteCookie.read()){login=opt(await api.loginWithSuite(suiteCookie.read()));if(!login)suiteCookie.clear();}if(login){session.save(login.token);session.saveSuite(login.suiteToken);}
 if(!token())return;const info=opt(await api.whoami(token()));if(!info){session.clear();return;}me=info.user;
 const hub=Actor.createActor(topbarIdlFactory,{agent,canisterId:info.hubId});topbar=mountTopbar($('topbar'),{hub:{actor:()=>hub,token:session.loadSuite()},hubUrl:HUB_URL,app:{id:'knowledge',name:'Doku',eyebrow:'Reviewed team knowledge'},person:me,onSignOut:signOut});
 $('login').hidden=true;$('workspace').hidden=false;$('proposalNav').hidden=!author();await route();
 setInterval(async()=>{try{const current=opt(await api.whoami(token()));if(!current){clear();me=null;$('workspace').hidden=true;$('login').hidden=false;session.clear();signIn.status('err','Your access expired. Sign in again.');}else if(current.user.role!==me.role){me=current.user;await route();}}catch{note('Connection interrupted. Changes are not confirmed until saved.',true);}},30000);
 }catch(e){if(publicMode){$('shared').hidden=false;$('shared').innerHTML='<div class="empty"><h1>Could not open this link.</h1><p>Check your connection and reload the page.</p></div>';}else signIn?.status('err',e.message||'Could not open Doku. Please try again.');}finally{signIn?.ready();}}
start();
